//www.stefankober.de/essays/questions-possibilities-and-formal-systems/04/":{"tf":1.0},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/05/":{"tf":1.0},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/09/":{"tf":1.0}},"df":6}}}}}}}},"r":{"docs":{},"df":0,"e":{"docs":{},"df":0,"a":{"docs":{},"df":0,"c":{"docs":{},"df":0,"h":{"docs":{"https://www.stefankober.de/essays/participation/06/":{"tf":1.0}},"df":1}}},"c":{"docs":{},"df":0,"u":{"docs":{},"df":0,"r":{"docs":{"https://www.stefankober.de/essays/conviction-formation/05/":{"tf":1.0}},"df":1,"r":{"docs":{"https://www.stefankober.de/essays/conviction-formation/09/":{"tf":1.0}},"df":1},"s":{"docs":{"https://www.stefankober.de/essays/recursion-tables/":{"tf":1.0},"https://www.stefankober.de/essays/recursion-tables/01/":{"tf":1.0},"https://www.stefankober.de/essays/recursion-tables/06/":{"tf":1.0}},"df":3}}}},"v":{"docs":{},"df":0,"e":{"docs":{},"df":0,"a":{"docs":{},"df":0,"l":{"docs":{"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/03/":{"tf":1.0}},"df":1}}},"o":{"docs":{},"df":0,"k":{"docs":{"https://www.stefankober.de/essays/participation/07/":{"tf":1.0}},"df":1}}}}},"s":{"docs":{},"df":0,"i":{"docs":{},"df":0,"m":{"docs":{},"df":0,"p":{"docs":{},"df":0,"l":{"docs":{},"df":0,"i":{"docs":{"https://www.stefankober.de/essays/conviction-formation/03/":{"tf":1.0}},"df":1}}}}},"t":{"docs":{},"df":0,"a":{"docs":{},"df":0,"b":{"docs":{},"df":0,"i":{"docs":{},"df":0,"l":{"docs":{"https://www.stefankober.de/essays/conviction-formation/06/":{"tf":1.0}},"df":1}}}}},"y":{"docs":{},"df":0,"s":{"docs":{},"df":0,"t":{"docs":{},"df":0,"e":{"docs":{},"df":0,"m":{"docs":{"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/":{"tf":1.0},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/08/":{"tf":1.0},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/09/":{"tf":1.0}},"df":3}}}}}},"t":{"docs":{},"df":0,"a":{"docs":{},"df":0,"b":{"docs":{},"df":0,"l":{"docs":{"https://www.stefankober.de/essays/recursion-tables/":{"tf":1.0},"https://www.stefankober.de/essays/recursion-tables/01/":{"tf":1.4142135623730951},"https://www.stefankober.de/essays/recursion-tables/02/":{"tf":1.0}},"df":3}}},"h":{"docs":{},"df":0,"e":{"docs":{},"df":0,"o":{"docs":{},"df":0,"r":{"docs":{},"df":0,"i":{"docs":{"https://www.stefankober.de/essays/conviction-formation-theory/":{"tf":1.0}},"df":1}}}},"i":{"docs":{},"df":0,"n":{"docs":{},"df":0,"g":{"docs":{"https://www.stefankober.de/essays/participation/05/":{"tf":1.0}},"df":1}}}},"i":{"docs":{},"df":0,"m":{"docs":{},"df":0,"e":{"docs":{"https://www.stefankober.de/essays/participation/08/":{"tf":1.0}},"df":1}}},"r":{"docs":{},"df":0,"u":{"docs":{},"df":0,"t":{"docs":{},"df":0,"h":{"docs":{"https://www.stefankober.de/essays/conviction-formation/07/":{"tf":1.0},"https://www.stefankober.de/essays/recursion-tables/01/":{"tf":1.0},"https://www.stefankober.de/essays/recursion-tables/02/":{"tf":1.0}},"df":3}}}},"y":{"docs":{},"df":0,"p":{"docs":{},"df":0,"e":{"docs":{"https://www.stefankober.de/essays/recursion-tables/03/":{"tf":1.0}},"df":1}}}},"v":{"docs":{},"df":0,"i":{"docs":{},"df":0,"s":{"docs":{},"df":0,"i":{"docs":{},"df":0,"b":{"docs":{},"df":0,"l":{"docs":{"https://www.stefankober.de/essays/recursion-tables/07/":{"tf":1.0}},"df":1}}}}}},"w":{"docs":{},"df":0,"i":{"docs":{},"df":0,"t":{"docs":{},"df":0,"h":{"docs":{},"df":0,"o":{"docs":{},"df":0,"u":{"docs":{},"df":0,"t":{"docs":{"https://www.stefankober.de/essays/participation/04/":{"tf":1.0}},"df":1}}}}}}}}}},"documentStore":{"save":true,"docs":{"https://www.stefankober.de/":{"body":"Conviction Formation Theory\nA cycle of essays about what can carry thinking and action amid competing convictions and standards, without certainty or a final foundation.\nRead Conviction Formation Theory\nEssays\nWriting on philosophy, reasoning, mathematics, and related questions.\nBrowse the essays\nArticles\nPeer-reviewed and preprint research.\nView the articles","id":"https://www.stefankober.de/","title":"Follow Your Curiosity"},"https://www.stefankober.de/about/":{"body":"Much of the work on this page revolves around Conviction Formation Theory, a research project on how convictions arise, stabilize, change, and sometimes fracture.\nThe world never quite seemed settled to me. Conviction Formation Theory grew out of that tension and continues to develop from it.\nI studied anthropology, philosophy, and musicology and graduated with an M.A. Later I completed a MicroMasters program in data science and earned a CISSP certification. I am currently studying mathematics on the side.\nI work in technical leadership roles in operations and IT security.\nIf you have thoughts, comments, or questions, please reach out:\nsk [dot] 1241 [at] nym [dot] hush [dot] com","id":"https://www.stefankober.de/about/","title":"About"},"https://www.stefankober.de/articles/":{"body":"Peer reviewed\nKober, S.: Radius-Guided Post-Clustering for Shape-Aware, Scalable Refinement of K-Means Results. J. Superintell. Comput. 2025, 1(1), 53-62.\nPreprint\nKober, S.: Radius-Guided Post-Clustering for Shape-Aware, Scalable Refinement of k-Means Results. arXiv preprint, arXiv:2504.20293.\n&nbsp; (peer-reviewed version available)","id":"https://www.stefankober.de/articles/","title":"Articles"},"https://www.stefankober.de/essays/":{"body":"2026\nConviction Formation Theory\nA cycle of essays about what can carry thinking and action amid competing convictions and standards, without certainty or a final foundation.\nRecursion Tables\nA visual notation for making the structure of recursive definitions easier to inspect and compare.","id":"https://www.stefankober.de/essays/","title":"Essays"},"https://www.stefankober.de/essays/conviction-formation-theory/":{"body":"A cycle of essays about what can carry thinking and action amid competing convictions and standards, without certainty or a final foundation.\nI. Forming And Revising Convictions\nA first cycle of essays examining how convictions form, how inquiry can reorganize them, and how finite agents participate without fully controlling what becomes convincing.\nConviction Formation\nQuestions, Possibilities, And Formal Systems\nParticipation\nII. Examining Constraint\nA second cycle of essays examining logic, probability, and causality, asking what makes their conclusions compelling, what they depend on, and how far their authority reaches.\nRecursive Examination\nLogic\nProbability Theory And Bayesian Updating\nPearl's Theory Of Causality\nRefinement, Pluralism, And What Remains","id":"https://www.stefankober.de/essays/conviction-formation-theory/","title":"Conviction Formation Theory"},"https://www.stefankober.de/essays/conviction-formation/":{"body":"","id":"https://www.stefankober.de/essays/conviction-formation/","title":"Conviction Formation"},"https://www.stefankober.de/essays/conviction-formation/01/":{"body":"We live among people who understand the world differently.\nSometimes the differences are small. Two engineers disagree about the likely cause of a failure. Two friends remember a conversation differently. A doctor and patient assign different weight to the possible side effects of a treatment.\nSometimes the differences reach much further.\nReligions disagree about what exists and what ultimately matters. Philosophical traditions disagree about knowledge, morality, mind, freedom, and reality. Political traditions disagree about justice and legitimate authority. Scientific theories can disagree about how observed phenomena should be explained. Cultures and institutions differ in their expectations, categories, and practices. Individual people inherit different histories and develop different ways of understanding what happens around them.\nPeople can disagree about what evidence is, which authorities deserve trust, what constitutes a good explanation, which distinctions matter, what should be regarded as morally relevant, or which procedures are legitimate.\nBut people with very different comprehensive views also share large regions of practice. They may use the same arithmetic, repair the same machines, recognize the same traffic signs, measure temperatures with the same thermometer, follow the same legal procedure, or discover the same bug in a computer program. A devout Christian, a Buddhist, an atheist, and someone who has never cared much about religion need not develop different methods for determining whether a door is locked.\nSome things settle easily between people who disagree deeply elsewhere. Other things remain disputed among people who otherwise understand one another very well.\nThe practical difficulty is that we cannot first settle all of this.\nA person considering whether to leave a marriage cannot postpone the decision until moral philosophy has been completed. A judge cannot wait until philosophers agree on the nature of truth and responsibility. Someone deciding whether to trust a warning must act before possessing a final theory of testimony. A voter cannot inspect every relevant fact and resolve every dispute about political legitimacy before making a choice. A scientist working between competing explanations cannot stand outside all theoretical commitments before interpreting an experiment.\nWe may have criteria, methods, arguments, and standards that convince us strongly. But their authority is not simply available from a final standpoint outside every further question. They too can be challenged, defended, revised, or rejected.\nWe believe and doubt. We inquire. We trust and distrust. We decide what deserves attention, make commitments, coordinate with others, and revise our judgments.\nWe act, and sometimes discover later that we acted badly.\nThe problem is not merely that human beings lack certainty. It is that finite agents must orient themselves while many of the larger questions that could ground their orientation remain unsettled.\nOne response would be to search for the correct comprehensive framework first.\nThat project may be worthwhile.\nBut it creates a practical problem of its own. For the search itself we already need to judge evidence, understand arguments, trust some procedures, reject others, decide which questions matter, and continue living while the search proceeds. We cannot suspend every conviction in order to investigate conviction from nowhere.\nWhat then can finite agents investigate and do while these larger disputes remain unresolved?\nPeople become convinced of things. Some matters seem obvious to them. Others remain doubtful. Some judgments survive criticism for decades. Others disappear after one conversation. Some ways of reasoning exert enormous force. Some arguments leave one person convinced and another untouched. New experiences reorganize old judgments. Questions reopen matters that had seemed settled.\nThese processes happen whether or not we possess a final philosophical explanation of them.\nA theory that cannot accommodate the fact that people become convinced differently under different orientations would fail to describe the phenomenon it is meant to explain.\nThus instead of first asking what final standard should govern conviction, we can decide to examine how conviction actually forms, acquires force, stabilizes, changes, and participates in orientation and action.\nWe can ask how far we can proceed before the larger questions are settled.\nThis does not replace the question, \"Is this true?\" with the question, \"Does this convince me?\"\nThese are different questions and they deserve different treatment.\nBut choosing a preferred framework of truth, justification, rationality, or inquiry does not make the phenomenon of conviction disappear. Its arguments, standards, and procedures must themselves acquire convincing force for finite agents, and can also become objects of investigation.\nConviction formation can become an object of investigation even while disputes about truth, justification, rationality, and inquiry continue.","id":"https://www.stefankober.de/essays/conviction-formation/01/","title":"1. The Predicament of Finite Orientation"},"https://www.stefankober.de/essays/conviction-formation/02/":{"body":"Suppose someone tells you: \"The meeting starts at ten.\"\nYou may repeat the sentence without believing it. You may have been asked to pass the message along.\nYou may act on it without being convinced. Maybe your manager told you to arrive at ten and you obey, although you privately suspect the meeting actually starts at eleven.\nYou may agree for strategic reasons. An argument about the starting time can have become tiresome and you say, \"Fine, you're right,\" merely to end it.\nYou may also genuinely expect the meeting to begin at ten. You arrange your morning around it. You become surprised when nobody appears. You begin looking for an explanation.\nThe last is the kind of case that interests us here.\nA conviction is something a person is convinced of. But that only moves the problem further, to a definition of being convinced.\nWe can begin with a clear central case:\nA person who is convinced of something ordinarily relies on it as a basis for further expectation, interpretation, reasoning, judgment, or action without even getting the idea that there is something to settle at that moment.\nThat means being convinced is not directly observable in another person. No single behavior reveals it. People can speak and act under instruction, coercion, convention, habit, strategy, or on the basis of assumptions they do not themselves believe. What we observe instead are patterns of reliance, expectation, surprise, reconsideration, and action from which conviction can be inferred.\nConvictions can shape interpretation and reasoning, guide judgment and action, and affect what appears surprising, threatening, relevant, possible, admirable, or absurd.\nBut they do not need to be simply present or absent.\nSometimes the language of degree seems natural.\n\"I think Peter did it, but I'm not sure.\"\n\"I'm almost certain the train leaves at six.\"\n\"I have a vague suspicion that something is wrong.\"\nIn such cases, how confident we are and whether we rely on something can come apart. We may rely on something while remaining uncertain about it, or be highly confident about something that matters little for what we do next.\nConviction also need not be consistent throughout a person. Different parts of their orientation can support incompatible patterns of reliance at the same time.\nStill, these cases resemble the clear case closely enough that it remains useful to call them convictions.\nThe word belief will remain useful in its ordinary broad sense. Conviction will be used when the convincing force of something, or the way it participates in further orientation, is specifically at issue.\nConvictions need not be explicitly formulated.\nYou may never have stated that a certain friend is dependable. Yet you call them first when something goes wrong.\nA skilled programmer may rely on distinctions that would take considerable effort to put into words. Someone walking through a familiar city may expect a street to continue behind a building without ever explicitly thinking, “The street continues behind that building.”\nMuch of what guides us operates without first becoming a sentence.\nThis also limits how directly we can inspect it. We sometimes discover what mattered to us only after acting, hesitating, regretting, or being challenged.\nWe do not have complete access to conviction formation, but we seem to be able to observe enough of it to investigate it.","id":"https://www.stefankober.de/essays/conviction-formation/02/","title":"2. What Is a Conviction?"},"https://www.stefankober.de/essays/conviction-formation/03/":{"body":"There is an easy experiment.\nTake a statement you currently find implausible.\nSuppose, for example, that you do not believe ancient extraterrestrials visited Earth and helped build early civilizations.\nNow decide to believe it.\nNot to imagine it.\nNot to entertain the possibility.\nNot to repeat the sentence.\nNot to play the role of someone who believes it.\nSimply become convinced that it happened.\nFor many people, nothing much follows from the decision.\nThey can say, \"Ancient aliens built the pyramids,\" write it down, or imagine how the world would look if it were true.\nThey could even spend an afternoon behaving as if they believed it.\nBut the proposition still does not become convincing merely because they have issued themselves an instruction.\nIf you already believe the ancient-aliens claim, reverse the experiment. Decide that it is false.\nThe same pattern is easy to reproduce with other examples. Clear counterexamples are much harder to find.\nMore than that, the idea of simply deciding to become convinced of something, without changing anything else, is difficult even to make sense of as an ordinary act of choice.\nCould you decide to become convinced that a spider is cuter than a ladybug?\nOur practices of persuasion, inquiry, teaching, and even manipulation seem to assume the opposite: we try to change what someone encounters, notices, considers, or experiences so that conviction may change.\nThis gives us the fundamental claim of Conviction Formation Theory:\nBecoming convinced is not under direct voluntary control.\nThis is a substantive claim, and it can be challenged. A genuine case in which a person is not convinced of something, deliberately decides to become convinced of it, and becomes convinced as a consequence of that decision would count against it.\nMore concretely, a counterexample would have roughly this form:\nA person is not convinced of P.\nThey deliberately decide to become convinced of P.\nNo new reason, evidence, experience, reinterpretation, attentional shift, or other relevant change intervenes.\nThey then become convinced of P as a consequence of that decision.\nThe important point is the third condition. A change from not being convinced to being convinced is not enough. What matters is whether the decision itself produced the change.\nIn an actual case, distinguishing this from changes in evidence, experience, attention, interpretation, or other conditions may not always be easy. Particular cases would have to be decided on the evidence.\nA convincing counterexample would be interesting beyond Conviction Formation Theory. If people can sometimes bring conviction under direct voluntary control, even under restricted conditions, that would reveal a capacity whose boundaries would immediately become worth investigating. Could it be learned or trained? Does it occur only under unusual conditions? Could someone acquire a useful conviction they currently lack by fiat, simply because having it would help them? These questions sound strange precisely because the capacity itself currently seems strange. A clear counterexample would make them empirical questions.\nThis matters for the problem with which we began. We cannot solve disagreement simply by deciding which convictions, criteria, or standards should govern us and then installing them by choice. Whatever role they acquire in our thinking, they too have to become sufficiently convincing to operate there.\nThe distinction becomes especially clear in ordinary perception.\nLook outside on a clear day.\nSuppose the sky appears blue.\nNow decide that it looks red.\nYou can say that it is red, imagine a red sky, close your eyes, or look through a colored filter. You can remind yourself that illumination, atmospheric conditions, and human vision are complicated.\nBut while you continue looking under ordinary conditions, you do not simply choose what appears.\nUnder ordinary conditions, what we perceive strongly constrains what we become convinced of about our immediate surroundings.\nWe can decide where to look.\nWe can decide to inspect something again.\nWe can move closer.\nWe can switch on a light.\nWe can ask someone else what they see.\nBut once we look, that part of what follows is not decided by us.\nSomething appears.\nWe can deliberately initiate some of the processes under which convictions form, but we do not directly determine their result.\nMental arithmetic offers another familiar example.\nCalculate 7 + 5.\nYou can decide to perform the calculation.\nYou can decide whether to use your fingers, count upward, remember an arithmetic fact, or check with another method.\nBut you do not choose which result will strike you as correct.\nYou can write \"13\".\nThat does not make 13 convincing.\nThe influence we can exert is indirect.\nConsider the ancient-aliens example again. Instead of issuing yourself the command \"Believe this,\" change the conditions. For weeks, read only material defending the idea. Watch sympathetic documentaries. Spend time with people who already accept it. Avoid criticism. Encounter the same examples repeatedly.\nMaybe nothing changes. But maybe what at first seemed absurd could begin to seem possible, then even convincing.\nThe same indirect structure appears in very different settings, but the conditions matter. In the ancient-aliens example, influences that might push the other way are deliberately reduced. In other situations, they remain present.\nA mathematics teacher chooses examples and exercises but cannot choose what the student will understand. A scientist can run another experiment without being able to control what the result will convince her of. Someone angry can postpone a message until morning because what seems convincing in anger may not remain convincing later.\nIn all these cases, people alter conditions under which conviction may later change, without controlling all the other influences at work: information, attention, exposure, practice, social surroundings, timing, questions, procedures, or physical circumstances. None guarantees a particular result.\nLack of direct control is not lack of influence.\nWe can participate in the conditions under which conviction forms without choosing the result.","id":"https://www.stefankober.de/essays/conviction-formation/03/","title":"3. Conviction Is Not Simply Chosen"},"https://www.stefankober.de/essays/conviction-formation/04/":{"body":"Imagine receiving a short message from a close friend: \"Fine.\"\nWhat does it mean?\nThere is no answer in the word alone.\nIf you have just proposed meeting at seven, it may mean agreement.\nIf you have been arguing for an hour, it may sound irritated.\nIf your friend habitually writes in short messages, nothing may seem unusual.\nIf they normally write warmly and expansively, the same word may become alarming.\nA tiny piece of information enters an already structured situation.\nThe situation helps determine what the message can become evidence for.\nConviction forms against such a background. When something new occurs, much is already in place.\nWe have previous convictions, expectations, language, concepts, memories, skills, habits, and relationships. We have distinctions, ways of interpreting situations, social practices, physical circumstances, questions already occupying us, and practical commitments.\nNew information enters this background and may confirm, disturb, extend, or reorganize parts of it.\nThis presently operative background through which a person finds their bearings can be called orientation.\nIt may include convictions, but it is broader than conviction. An unresolved question, a practical skill, an unformulated expectation, a perceived possibility, or a commitment such as having promised to meet someone tomorrow can all be part of someone's orientation. So can memories and relationships that make some interpretations immediately plausible and others remote.\nOrientation is an organizing term for these already operative conditions.\nThis matters because new convictions depend partly on what is already there.\nConsider a toddler and an astronomer looking at the night sky.\nThe same visible points of light can participate in very different orientations.\nThe astronomer may see a planet, recognize a constellation, notice atmospheric distortion, or infer something from apparent movement.\nThe toddler does not merely possess fewer propositions about the same scene. Different distinctions are available, other questions can arise, and different things may become salient.\nOr consider a sentence in an unfamiliar language.\nFor someone who cannot read it, the marks may be recognizable as writing without carrying much further structure.\nFor a fluent reader, meaning can appear almost automatically.\nTraining has changed what the same marks can do.\nNew information does not arrive into an empty space. It is encountered through the active elements of an existing orientation.\nStories\nOne especially important way human beings organize situations is through stories.\nSuppose you see a colleague leave a meeting abruptly.\nYou might connect the event with what happened earlier.\nSomeone may have insulted her.\nShe may have received an urgent message.\nPerhaps she was angry about a decision.\nOr she simply had another appointment.\nThe event acquires different meanings depending on the surrounding story.\nStories can organize who is involved, what happened, how events connect, what preceded them, what people intended, what might happen next, and what matters about all of it.\nThis is not restricted to polished narratives.\nMuch everyday understanding has this form.\nSomeone says:\n\"He has been distant since Monday.\"\n\"We were getting along until that argument.\"\n\"She promised to call, but then this happened.\"\nThe events are being connected into a provisional whole that makes further expectation and action possible.\nStories can participate strongly in conviction formation. If you become convinced that a colleague deliberately humiliated you, later events may be interpreted against that background. A neutral remark can acquire significance. An apology may be treated as insincere. A forgotten meeting may become further evidence.\nWe often organize particular situations this way. A disagreement with a friend becomes part of the story of that relationship. A difficult year becomes part of the story of a life. Events at work become part of a story about an institution, a profession, or how things are done there. These stories often connect with broader ones about groups, places, societies, or a life as a whole.\nOther parts of orientation need not be organized primarily as stories. Navigating a room may rely mainly on spatial orientation. Performing a familiar task can be procedural. A mathematical proof may be represented symbolically or diagrammatically. An affective response may arise before any story about it becomes available.\nOrientation is the broader term. Stories are one important way in which parts of it can be organized and connected.","id":"https://www.stefankober.de/essays/conviction-formation/04/","title":"4. Conviction Forms Against a Background"},"https://www.stefankober.de/essays/conviction-formation/05/":{"body":"We can now look more closely at some conditions under which convictions form and acquire force.\nWhat follows is not an exhaustive list.\nSome are ordinary observations. Some are plausible interpretations of those observations. Their interaction is likely to vary substantially between persons, domains, and situations.\nThe purpose is to identify recurring patterns worth investigating.\nAttention and Salience\nImagine walking through a city with an architect.\nYou notice shops, people, traffic, perhaps whether the street feels pleasant.\nThe architect notices window proportions, materials, load-bearing structures, the transition between old and new buildings.\nWalk the same street with a security specialist and different things may stand out again.\nEntrances, blind corners, lighting, and crowd movement for example.\nNothing requires the three people to disagree.\nThey may simply be attending to different things.\nReasoning does not usually begin from a neutral inventory of everything present.\nSomething first becomes relevant enough to enter the process.\nA remark that previously passed unnoticed becomes an insult.\nCracks in a wall may suddenly matter once you know what structural movement looks like.\nA teacher can point out a musical detail that you had never noticed before.\nAnd after learning what a symptom can indicate, it may become alarming.\nAttention can sometimes be directed deliberately.\nLook here. Compare these two. Listen to the bass line. Check what happens immediately before the error.\nBut salience can also be produced by events themselves.\nA loud noise interrupts. Pain captures attention. A frightening possibility becomes difficult not to consider.\nTexts, diagrams, interfaces, environments, and other people can all reorganize what stands out.\nDifferences in conviction begin before explicit disagreement.\nOne person sees a problem. Another does not yet see anything there to disagree about.\nWhat becomes salient can alter what becomes available for further conviction formation.\nPerception and Affect\nSome convictions acquire force without first passing through an explicit argument.\nYou look outside and see that it is raining. You hear a crash and become convinced that something fell.\nIn other cases, affect participates in what becomes convincing. A remark strikes you as cruel. Someone you trusted suddenly seems threatening. A piece of music strikes you as beautiful.\nThese are distinguishable cases. Perception, affect, evaluation, and interpretation may contribute in different ways. What they share is only that explicit reasoning need not come first.\nPain, fear, disgust, attraction, empathy, and anger can change what becomes salient and how a situation is interpreted before any explicit argument is made. Anger, for example, can temporarily make hostile interpretations seem compelling and alternatives remote. When it subsides, some of that convincing force may disappear with it.\nExperience, Repetition, and Practice\nConvictions can acquire stability through repeated experience.\nA friend repeatedly keeps promises.\nThe same instrument gives the expected reading again and again.\nA familiar procedure continues to produce the expected result.\nTrust can grow without any single decisive event.\nBut repetition does not strengthen conviction by itself.\nExposure can produce boredom or resistance, something initially striking can disappear into the background, and repeated failure can weaken confidence instead.\nWhat matters is what happens through repeated encounters within a particular orientation. Repeated success can stabilize a conviction. Repeated failure can weaken one. Neither result follows from repetition alone.\nExperience and practice can also change the orientation against which later convictions form.\nConsider learning to drive.\nAt first, many things require deliberate attention.\nMirrors.\nClutch.\nGear.\nSpeed.\nLane position.\nOther vehicles.\nWith practice, distinctions that once demanded effort become readily available, and some responses become almost automatic.\nSomething similar happens in more specialized practices.\nAn experienced radiologist may notice distinctions in an image that a beginner misses. Similar changes occur in other learned practices: a musician begins to recognize relations that once passed unnoticed, or a mathematician sees structures that previously required laborious reconstruction.\nPractice has not merely added information. It has changed what can be noticed, recognized, or handled readily.\nWhatever the underlying cognitive explanation, experience and learned practices can alter both existing convictions and the conditions under which later conviction forms.\nInteraction and Social Reinforcement\nConvictions also form between people.\nYou tell someone what happened.\nThey believe you.\nOr they look doubtful.\nSomeone points out an alternative you had not considered.\nA group may laugh at a remark.\nThe teacher corrects your answer.\nA colleague says, \"That is exactly what I saw.\"\nOr a friend asks, \"Are you sure?\"\nSuch responses can reinforce, destabilize, redirect, or leave conviction untouched.\nPeople encounter not only explicit instruction, but approval, correction, imitation, surprise, disapproval, and expectations about what \"people like us\" do.\nOver time, some of these patterns can become deeply familiar.\nSimilar processes continue in adult life.\nProfessions and institutions preserve methods and procedures. Religious, scientific, familial, and political communities can carry texts, practices, expectations, categories, and standards across long periods.\nConvictions can acquire part of their stability through participation in durable social structures.\nAnd when those structures change, conviction may change with them.\nIntegration\nSome convictions are hard to disturb because many parts of a person's orientation support them at once.\nSuppose someone has been convinced for decades that close friendship is important.\nThat conviction may connect with memories, habits, plans, identity, relationships, moral judgments, and expectations about a worthwhile life.\nChallenging it is not like replacing one isolated item in a list.\nMany things may have to move.\nA political or religious conviction may become connected with relationships, identity, memories, practices, and ways of interpreting events. Convictions about oneself can similarly affect which ambitions seem possible and which failures seem intelligible.\nThis suggests a strong hypothesis:\nConvictions integrated with many active parts of orientation may often resist local disturbance more strongly than relatively isolated convictions.\nBut the hypothesis should not be mistaken for a principle of justification.\nIntegration can support false convictions.\nA conspiracy theory can integrate observations, identity, community, and distrust into a highly resilient structure.\nRemoving one piece may accomplish little because the rest continues to hold.\nThis is a hypothesis about persistence, not about merit. A conviction does not become better justified merely because many parts of a person's orientation support it.\nThat distinction matters because the same conditions can play different roles. Reasons, evidence, methods, and criteria may give us grounds for judging one conviction better supported than another. They may also participate in changing what someone is actually convinced of. Since conviction is not under direct voluntary control, these two questions cannot simply be collapsed: what should convince us, and what in fact becomes convincing, are related but distinct.\nHere we are concerned with the second question. We can investigate why an integrated conviction survives local challenge without treating that survival as evidence in its favor.\nIntegration may explain persistence. It does not vindicate what persists.","id":"https://www.stefankober.de/essays/conviction-formation/05/","title":"5. Recurring Conditions of Conviction Formation"},"https://www.stefankober.de/essays/conviction-formation/06/":{"body":"The previous examples repeatedly used words such as stable, resilient, and settled.\nA conviction is stabilized insofar as it continues to operate despite disturbances that might otherwise have changed it, over some period and under some conditions.\nStability is local rather than absolute.\nYou can remain convinced that a colleague is dependable until an unexplained event occurs. Political convictions may survive criticism within one social environment and weaken after years spent in another. A moral judgment that seems settled in calm conditions may become less secure under fear or anger.\nA conviction is stable for this person. Under these conditions. Against these disturbances. Over this period.\nDifferent stabilizing conditions may also combine. Perception may repeatedly confirm what is expected, while habit can reduce occasions for reconsideration. A social group may reinforce a conviction. Formal arguments can connect convictions with other accepted premises. Repeated practical success may strengthen reliance. Identity can make alternatives difficult to integrate.\nStabilization is not certainty. A person can retain doubts while continuing to rely on a conviction.\nNor is stabilization permanence. Even convictions that survive for decades can change.\nStability tells us something about how a conviction persists, not about its merit.","id":"https://www.stefankober.de/essays/conviction-formation/06/","title":"6. Stabilization"},"https://www.stefankober.de/essays/conviction-formation/07/":{"body":"At this point we can return briefly to the problem with which we began.\nDifferent frameworks make different claims about what is true.\nThey may also disagree about how truth should be understood, which evidence matters, or what procedures deserve authority.\nConviction Formation Theory does not set out to settle these disputes.\nBut it still matters which questions about truth bear on the present investigation.\nSeveral different issues have sometimes been grouped together under the word truth. Separating them helps show which of those issues matter here.\nFirst, there is an ordinary, pretheoretic use of truth in which things can be a certain way independently of what someone happens to believe, and what we say can get them right or wrong.\nIf I am convinced that my keys are on the table and they are actually in my coat, my conviction does not relocate the keys.\nSecond, there are philosophical theories of truth.\nCorrespondence theories, deflationary theories, pragmatic theories, pluralist theories, and others attempt to explain what truth consists in or what truth-talk does.\nThird, there is a stronger epistemic hope sometimes attached to truth: that appeal to truth might itself provide finite agents with a final, non-circular procedure telling them what to believe, or a foundation from which inquiry can be conclusively settled.\nWhether such a foundation is available is a different problem. Nothing here requires us to assume that it is. Nothing shows that it is not.\nThe methodological claim is:\nMany questions concerning conviction formation can be investigated without first settling a theory of truth or obtaining a final epistemic foundation.\nThis applies to Conviction Formation Theory itself. A reader cannot simply decide to become convinced by it. The distinctions and arguments offered here must acquire enough force to be taken up, examined, and used. They need not first be established as the final truth about conviction formation before that can happen. A framework can become useful in inquiry while remaining open to criticism, revision, or rejection.\nBeing convincing does not thereby make CFT true. Its substantive claims can still turn out to be untenable. But their truth need not be settled in advance for the investigation to begin.\nWe can keep two questions apart:\nHow does this become convincing?\nand\nIs it true?\nThe present investigation addresses the first, but not the second.\nBut the idea that our convictions can sometimes become better constrained because they answer to how things are may itself be a very convincing explanation of some of our abilities to form and correct convictions.\nWe do not need to possess a detailed theory of correspondence that convinces us in every respect for that explanation to have force.\nConviction can outrun theory here too.","id":"https://www.stefankober.de/essays/conviction-formation/07/","title":"7. Truth and Conviction Formation"},"https://www.stefankober.de/essays/conviction-formation/08/":{"body":"Convictions do not only form and stabilize.\nThey weaken, fracture, become qualified or reorganized, and sometimes disappear.\nThe processes are often easiest to see when something that once felt obvious stops doing so.\nContradiction and Tension\nSuppose Peter is accused of a crime.\nA witness identifies him at the scene.\nBut Peter's friend insists that Peter was with him somewhere else at the relevant time.\nIf both claims initially convince you, they cannot remain comfortably side by side once the conflict becomes salient.\nThe witness may have been mistaken, or the friend may be lying. Perhaps the timeline was misunderstood, Peter left and returned, or one of the reports was described inaccurately.\nThe contradiction does not determine which conviction should change.\nIt creates pressure.\nPeople respond to such pressure in different ways.\nThey may revise or qualify one conviction, reinterpret the situation, compartmentalize the conflict, avoid it, or abandon one of the convictions.\nSometimes they tolerate inconsistency for a long time until circumstances force it into attention.\nA contradiction that is never noticed need not destabilize anything.\nA contradiction that becomes salient may reorganize an entire field.\nFormal systems make some contradictions difficult to ignore because the conflicting consequences can be explicitly reconstructed. Everyday life is often less tidy.\nQuestions\nA question can also destabilize without directly asserting the opposite of a conviction.\nSuppose you have become convinced that a colleague ignored you deliberately.\nThen someone asks: \"What else could explain it?\"\nAll of a sudden, alternatives may reopen.\nThe colleague may not have seen you, may have been distracted, or perhaps was responding to something else.\nA question can turn what had been treated as settled back into something examinable, make an assumption visible, redirect attention, or create space around a conclusion.\nThis does not mean questioning always weakens conviction.\nA challenge may strengthen it.\nUnanswered questions may disappear.\nGood questions may expose an overlooked difficulty, while a bad one merely distracts.\nThe role of questions is large enough to require separate treatment.\nFor now, it is enough that questions can reopen parts of orientation that had become relatively closed.\nFailed Practice\nSome convictions weaken in use.\nSuppose you are convinced that a particular shortcut saves time.\nYou take it repeatedly.\nAgain and again, traffic makes the route slower.\nAt some point the conviction may become difficult to sustain.\nA software diagnostic procedure may work reliably for years and then begin identifying the wrong component after an architectural change.\nThe same pattern can occur when a theory repeatedly predicts events that fail to happen, or when an interpretation of someone's behavior keeps leading to surprise.\nHere the destabilizing force comes from breakdown.\nSomething relied upon stops working as expected.\nThis does not determine exactly what should be revised. But it can make continued reliance harder to sustain.\nRepeated breakdown can become a source of destabilization.\nLoss of Reinforcement\nImagine someone leaving a close-knit religious community.\nFor years, particular convictions were renewed through conversation, ritual, shared texts, friendships, calendars, and expectations.\nAfter leaving, the person may initially remain just as convinced.\nBut some of the conditions that repeatedly returned those convictions to attention are gone.\nMonths or years later, things that once seemed obvious may feel more distant.\nThe same can occur when leaving a profession, political movement, social group, relationship, or institution.\nReinforcement can be one condition of stability.\nRemove the condition and stability may change.\nSometimes the opposite happens. Leaving a group strengthens a conviction precisely because opposition makes it more salient.\nTransformation and Dissolution\nNot every destabilized conviction disappears.\nSuppose someone believes: \"My father was a bad person.\"\nLater they learn more about his circumstances.\nThe conviction may weaken.\nOr narrow: \"He treated us badly during those years.\"\nIt may become conditional: \"I still think what he did was wrong, but I no longer think it defines him.\"\nIt can transform: \"I used to understand his behavior as cruelty. I now understand much of it as fear.\"\nOr dissolve: \"I simply don't see him that way anymore.\" Another conviction may replace it.\nThese changes are not equivalent.\nWeakening concerns force, while narrowing restricts scope. Conditionalization adds conditions that were previously absent. A conviction can also be transformed, dissolved, or replaced by another.\nThe boundaries are not always clear.","id":"https://www.stefankober.de/essays/conviction-formation/08/","title":"8. Destabilization and Change"},"https://www.stefankober.de/essays/conviction-formation/09/":{"body":"Some convictions disappear almost without leaving a trace.\nA childhood fear may become difficult even to remember.\nAn old ambition can lose all force.\nJudgments about someone simply cease to matter.\nOther convictions remain for decades.\nAnd still others disappear, then return.\nThese are different patterns.\nA persistent conviction continues to participate in orientation even if it is rarely explicit.\nSomeone may spend years without thinking about the importance of friendship, yet organize major decisions around it whenever the issue arises.\nA conviction can leave attention without disappearing.\nDisappearance is stronger.\nThe conviction then no longer participates in orientation.\nA person may remember having believed something without being able to recover its former force.\n\"I know I once thought that, but I can't understand anymore why it seemed obvious.\"\nRecurrence occurs when something that had ceased to operate becomes convincing again.\nOld political convictions can return when circumstances change. Religious convictions sometimes disappear and later re-emerge. A judgment about another person may become convincing again after a new event.\nDistinguishing persistence from recurrence is not always easy, especially from the outside.\nIf a conviction returns after twenty years, was it absent or merely dormant?\nThat may depend on what we mean by participating in orientation, and the evidence can be thin.\nStill, the distinction is useful.\nThe conditions already discussed offer several possible explanations for persistence.\nRepeated reinforcement may keep a conviction active, while integration with memories, habits, plans, and other convictions can make it harder to disturb. Social surroundings may continually renew it, and recurring circumstances can reactivate the same pattern.\nDifferent forms of persistence may have different support.\nThe persistence of \"fire burns\" is not obviously sustained in the same way as the persistence of \"family matters.\"\nOne is repeatedly reinforced through a stable class of interactions.\nThe other may be integrated with relationships, identity, memories, obligations, hopes, and a life history.\nThe word persistence describes the temporal phenomenon.\nIt does not tell us why the phenomenon occurs.\nQuestions show related patterns.\nSome disappear when a sufficiently convincing answer arrives.\n\"Where is the station?\"\nOnce you arrive, the question no longer participates in orientation.\n\"How do I reset this device?\"\nOnce the procedure is learned and the problem solved, the question may vanish.\nOther questions recur.\n\"What should I do with my life?\" can seem settled at twenty-five and return at forty.\nSome questions appear to persist through changing answers.\nQuestions concerning justice, meaning, consciousness, knowledge, or how to live can remain active in a person's life even while successive answers become convincing for a time.\nWhat gives rise to them may be too broad or persistent to be exhausted by one answer. But persistent questions need not persist for the same reason at all.\nPersistent questions matter because conviction does not simply accumulate until everything has been settled.\nWhat has settled in orientation can become unsettled again.","id":"https://www.stefankober.de/essays/conviction-formation/09/","title":"9. Persistence and Recurrence"},"https://www.stefankober.de/essays/conviction-formation/10/":{"body":"Several things can remain convincing at once without pointing in the same direction.\nSuppose two witnesses describe the same event differently, and both seem credible.\nNeither report disappears because the other exists, and both exert pressure.\nOr suppose a doctor recommends a treatment that appears likely to help but carries serious possible side effects.\nThis is advisable in one respect and troubling in another.\nSometimes nothing settles immediately.\nWe remain uncertain.\nWe may lean one way while still finding opposing considerations difficult to dismiss.\nConviction formation can involve more than something simply convincing or failing to convince. Different considerations can convince in different directions.\nWeighing\nOrdinary language already has a useful word for what often follows.\nWe weigh what speaks for one possibility against what speaks for another.\nThe metaphor should not be taken literally. There need not be a hidden scale in the mind.\nIt captures something simpler: several considerations can remain active at once and bear differently on what eventually becomes convincing.\nSuppose you are unsure whether a colleague deliberately excluded you from an important conversation.\nYou remember earlier tensions.\nYou also know that the colleague was under strong pressure that day.\nSomeone tells you the omission was accidental.\nYou can remain with the situation as it stands.\nBut you can also do things.\nYou can seek further information, ask what else might explain what happened, inspect an assumption, or introduce another possibility. You might look for an objection to the view you currently favor, or return to the question later.\nWhat you cannot do in the same way is decide where the weight will fall.\nYou can choose to inspect an objection without being able to choose whether it will cease to trouble you. You can reconstruct an argument without being able to command yourself to find it convincing.\nDeliberation is both active and receptive.\nWe can influence what enters the weighing and how carefully it is examined.\nWe cannot directly assign convincing force.\nCriteria\nSometimes parts of orientation become stable enough to organize later weighing.\nSuppose you are choosing a car.\nPrice matters to you.\nSo does safety.\nReliability has become important after years of repairs.\nRunning costs matter because your budget is limited.\nOnce they have acquired enough force, they can function as criteria in the comparison.\nMaking them explicit can reveal why one option appears preferable and where different considerations conflict.\nCriteria do not remove weighing.\nThey structure it.\nThey remain within conviction formation.\nYou can propose a criterion, apply it, compare it with another, and examine what follows. But you cannot simply decide that it will matter to you.\nOnce criteria become convincing enough, they can operate as relatively settled parts of an inquiry without being reconsidered at every step.\nDifferent people and practices may settle on different criteria.\nCriteria can also become unsettled again.\nA criterion may conflict with another.\nIts use may produce results that disturb confidence in it.\nSomeone may ask why it should matter at all.\nWhen that happens, the criterion itself can become part of the inquiry.\nNothing requires this questioning to continue indefinitely.\nCriteria can settle locally just as other convictions can.\nShared Criteria\nCriteria do not have to be shared in order to guide a person's own weighing.\nBut when people assess something together, shared criteria can provide common terms for comparison.\nSuppose two people disagree about which of two explanations is better.\nThey may already agree that an explanation should account for a particular observation.\nThat agreement does not settle the question.\nThey may still disagree about which explanation fits the observation better, how much weight it should carry, or what else matters.\nBut they do not have to reopen that criterion at every step.\nWhere enough criteria have become sufficiently stable for the people involved, they can organize a shared inquiry without becoming final or universal.\nWhere that overlap is missing, the disagreement may shift.\nOne person may appeal to a criterion that does not convince the other.\nThe criterion itself can then become part of the inquiry.\nShared criteria do not take inquiry outside conviction formation.\nThey are cases in which enough of what has become convincing overlaps for people to examine something together.\nDefensibility\nA conviction can be challenged.\nSuppose you are convinced that another person acted maliciously.\nSomeone asks why.\nBeing convinced does not answer the question.\nIf you take up the challenge, you have to offer something in defense of the conviction.\nYou might point to what was said, what happened before, or what alternatives seem unlikely.\nThe other person can examine what you offer, accept some of it, reject some, or ask for more.\nThe conviction is now being assessed from another perspective.\nIt no longer operates only within the orientation in which it formed.\nIt has become answerable to another perspective.\nA defense introduces a relation between people.\nSomeone offers considerations in support of a conviction.\nSomeone else assesses what is offered.\nThe person assessing the defense need not be neutral, authoritative, or final.\nThey may already disagree.\nThey may share some criteria with the person offering the defense and reject others.\nThis allows several things to come apart.\nConvictional strength concerns how firmly something convinces a person.\nA defense is what someone offers when that conviction is challenged.\nDefensibility concerns how that defense fares under the criteria operative in the assessment.\nPersuasion concerns whether the defense actually changes what the other person finds convincing.\nThese are not the same.\nA defense may fare well under criteria shared in an inquiry and still fail to convince the person assessing it.\nAnother defense may convince someone while faring poorly under those same criteria.\nSuccessful persuasion is not the measure of defensibility.\nNor must the considerations offered in a defense be the same things that originally made the conviction convincing.\nWhat formed or stabilized a conviction may carry little weight under the criteria now being used to assess it.\nA challenge can make that difference visible.\nSomeone may discover that they are strongly convinced of something but have little to offer under criteria they themselves accept. That may or may not change the convincing force of the conviction.\nOr they may find that considerations they had scarcely noticed before become important once the conviction has to be defended.\nDefensibility is local and relational.\nA defense is offered here, to these people, under these criteria, for this challenge.\nWhere enough criteria are shared, the defense can be assessed without every standard being reopened at once.\nWhere they are not, part of the disagreement may shift to the criteria themselves.\nDefense also creates another opportunity for deliberate participation.\nWe can clarify what we are claiming, offer further considerations, answer objections, compare alternatives, and apply criteria already operative in the inquiry.\nWhat we cannot do is decide that the defense will convince the person assessing it. Nor can that person.\nThe same applies in self-examination. We can ask ourselves to state the case for a conviction and examine what we produce. We cannot command ourselves to find that case convincing.\nThe fundamental claim applies here as well. A group can agree on procedures and criteria, invite criticism, and require claims to be defended. These arrangements can shape what happens next, but the group cannot simply decide what its members will find convincing.\nA conviction can become answerable beyond the orientation in which it first formed. Where enough criteria are shared, people can examine the defense together. But shared criteria still do not place what becomes convincing under either side's control.","id":"https://www.stefankober.de/essays/conviction-formation/10/","title":"10. Defensibility and Criteria"},"https://www.stefankober.de/essays/conviction-formation/11/":{"body":"We began with a practical problem.\nWhat can finite agents investigate and do while larger disputes about truth, justification, rationality, and foundations remain unresolved?\nThe preceding investigation gives us a partial answer.\nQuestions concerning how convictions form, stabilize, weaken, and change can be investigated without first settling those larger disputes.\nThis does not make truth or justification irrelevant.\nBut inquiry into conviction formation can begin before they are finally settled.\nThe same applies to Conviction Formation Theory itself.\nCFT need not first establish itself as the final truth about conviction formation before it can be examined, used, challenged, or revised.\nBeing convincing does not make it true.\nIts claims can still turn out to be untenable.\nParticipation Without Control\nThe fundamental claim was initially negative:\nBecoming convinced is not under direct voluntary control.\nBut lack of direct control does not leave us passive.\nWe can ask questions, seek information, introduce alternatives, compare, practise, expose assumptions, and invite criticism. We can make criteria explicit, defend convictions, and examine defenses.\nThese interventions can change the conditions under which conviction forms.\nThey do not determine the result.\nParticipation does not require a standpoint outside conviction formation.\nThe same limit applies when inquiry is shared.\nPeople can agree on procedures, use shared criteria, compare alternatives, and require claims to be defended.\nThey can organize inquiry together.\nThey cannot simply choose what its participants will find convincing. What becomes convincing among them must itself emerge and stabilize through the inquiry.\nSettlement Without Final Settlement\nInquiry would be impossible if everything had to remain open at once.\nConvictions stabilize.\nPractices stabilize.\nSome parts of orientation become stable enough to function as criteria.\nSome criteria become shared strongly enough to organize inquiry across people.\nSuch stability need not be permanent or universal.\nIt can be local to a person, a group, a practice, a set of conditions, or a period of time.\nThis gives us usable settlement. What has settled can carry further inquiry until something disturbs it.\nThat disturbance may come from a contradiction, a failed expectation, a question, another person, a competing criterion, or something else that acquires enough force.\nStability matters without vindicating what has stabilized.\nA stable conviction can be mistaken. A shared criterion can later be challenged, and settled practices can change.\nCFT treats settlement as something that happens within conviction formation, not as an endpoint outside it.\nLocal settlement can still do some of the work for which we might otherwise demand a firm scholarly foundation first. It can support further inquiry, coordinate action, and allow reasoning to continue while larger questions remain open.\nCriteria and Shared Inquiry\nCriteria do not have to be supplied from somewhere beyond conviction formation.\nA distinction, aim, procedure, or standard can become convincing and stable enough to organize later assessment.\nCriteria can be proposed, compared, and applied without putting their convincing force under our control.\nOnce operative, however, criteria can genuinely constrain an inquiry.\nWhere enough criteria are shared, people can assess something together without reopening every standard at every step.\nWhere they are not shared, disagreement may move to the criteria themselves.\nChallenge introduces another important possibility.\nA conviction that once operated within one person's orientation can become answerable to another.\nSomeone asks why. A defense is offered.\nWhat is offered can be examined under criteria available in the inquiry.\nConviction has become available for assessment across perspectives.\nLocating Disagreement\nPeople may disagree about what happened, which possibilities deserve attention, which considerations matter, or which criteria to use. They may even share a criterion but disagree about how it applies, or agree about the assessment without finding the same conclusion convincing.\nCFT does not settle these disagreements merely by distinguishing them.\nBut sometimes progress consists in discovering where the disagreement actually lies.\nA question may become more precise, another possibility may need attention, or the inquiry may shift to a criterion or comparison.\nInquiry Without Command\nConviction Formation Theory does not give us a final theory of truth, a universal standard of justification, criteria everyone must accept, or a standpoint outside conviction formation from which everything can finally be judged.\nIt gives us something more limited.\nConvictions form against an orientation already in place, and they can stabilize or become unsettled again. Questions can disturb what had seemed settled. Criteria can become stable enough to guide inquiry and shared enough to support assessment across people.\nThroughout this, finite agents can intervene without directly choosing what will convince them or anyone else.\nWe can alter conditions, ask questions, compare possibilities, expose assumptions, apply criteria, challenge and defend.\nWe can work with what has become convincing without pretending that it is final.","id":"https://www.stefankober.de/essays/conviction-formation/11/","title":"11. What Conviction Formation Gives Us"},"https://www.stefankober.de/essays/participation/":{"body":"","id":"https://www.stefankober.de/essays/participation/","title":"Participation"},"https://www.stefankober.de/essays/participation/01/":{"body":"An author can try to show how a conviction formed by presenting the questions that guided it, the distinctions that mattered, the examples that changed something, and the steps by which one view gave way to another.\nThe reader may then be able to walk that path.\nWhere that is not enough, an author can try to make a phenomenon visible or tangible enough to be examined in another way.\nBut texts cannot guarantee that convictions will form in the same way in every reader.\nTexts contribute to that formation by clarifying something, raising a question, making a comparison, or opening another possibility.\nBut they do not command the result.\nMore generally, people can ask questions, seek other possibilities, direct attention, use procedures, return to problems, or prepare before a situation occurs.\nSuch interventions can alter the conditions under which conviction forms without determining what will become convincing.\nConvictions form, and questions can become pressing without our choosing either.\nWhat, in all this, is actually our doing?","id":"https://www.stefankober.de/essays/participation/01/","title":"Introduction"},"https://www.stefankober.de/essays/participation/02/":{"body":"If you are like most people, you can hold up your fist and extend your index finger.\nYou can repeat that.\nBut you cannot move a chess piece across the board in the same way, merely by willing it to move.\nYou can, however, use movements of your hand to move it where you want it.\nYou can do that even when the move is not permitted by the rules of chess.\nYou can also use your other hand to extend the index finger from the example above.\nThis is not unheard of. Maybe it is very cold and the finger no longer moves as you want. Maybe you have a cramp.\nA sword is somewhere between the finger and the chess piece.\nYou can learn to use it as an extension of your body and, to a certain extent, feel what happens at its other end through your hand, even with your eyes closed.\nBut when you put it down, that connection is gone.\nYou can begin a calculation when you need the result. The answer is not something you can will into place either.\nYou are constrained by a formal system that works by its own rules.\nIf you are unsure, you can calculate again, maybe in a different but equivalent way.\nYou can choose to begin and how carefully to proceed, but you do not simply choose the result.\nNow imagine a ball rolling towards a precious vase.\nIf nothing intervenes, it will knock the vase over and break it.\nYou can intercept the ball.\nThen you have saved the vase from destruction.\nBut suppose you do not move.\nHave you failed to save it?\nThat may depend on whether you saw the ball, whether you could reach it, whether other persons could have saved it, what else would have happened, and why exactly you did not move.\nThe examples do not leave us with one obvious place where our doing begins.\nMoving a finger seems straightforward enough. A chess piece moves through movements of your body, and training can make a sword part of that movement. You can begin a calculation without choosing its result. You may save the vase by intervening, or fail to save it without moving at all.\nWhat makes all of this our doing?\nDoes our doing begin where we choose something?","id":"https://www.stefankober.de/essays/participation/02/","title":"What Is Our Doing?"},"https://www.stefankober.de/essays/participation/03/":{"body":"Choose a number between 1 and 10.\nHow did you do it?\nMaybe you waited for the right number to appear.\nMaybe you already had one in mind.\nOr maybe a number appeared with the question, or while you were preparing to answer.\nIs the chosen number your doing?\nIt came into the world by your fiat numerus.\nBut how exactly did you choose?\nThere does not seem to be one fixed way of choosing a number like that. The process seems receptive and active at once.\nBut this is an unusual kind of choice. There is no goal beyond choosing, and no obvious criterion by which one number would be better than another.\nSuppose the screw on one of the legs of your desk is loose.\nOn the desk lie a hammer, a screwdriver, and a knife.\nWhich tool do you choose?\nProbably the screwdriver. It is made for tightening screws.\nBut suppose the screwdriver is too large and the knife fits perfectly.\nThen maybe you choose the knife instead.\nHere the choice has a purpose.\nYou want to tighten the screw, and the available tools differ in how well they serve that purpose.\nYou may stop and reason about this.\nOr you may simply reach for the screwdriver.\nEither way, one possibility becomes the one you act on.\nBut were the hammer, screwdriver, and knife really all your possibilities?\nSuppose there were only a hammer, a knife, and a lighter on the table. You could ignore all three, walk to another room, and get a screwdriver.\nThe possibilities were not simply given by what happened to be in front of you.\nYou can alter, update and abandon the set.\nNow choose two names that potential partners of yours might have.\nReplace Hanna and Mary with those names while reading.\nHanna and Mary both have qualities you value, and qualities you do not. Which one, if either, should you choose as your partner in life?\nHere the situation is different again.\nThere may be many things that matter.\nAffection, trust, attraction, shared plans, character, family, and timing may all matter. Maybe some of these matter greatly and others only a little.\nBut even when the possibilities and relevant considerations are known, nothing in them may make one choice follow.\nBy the way, how did you choose the names? Or did you choose not to choose?\nSometimes we respond by choosing a procedure.\nA rule, a vote, a coin, or advice from someone we trust.\nIt changes where our participation lies.\nWe choose how the decision will be made.\nAnd then we allow something else to settle what happens next.\nDoes calculation belong here too? We choose to begin and follow the procedure, but not what result it yields.\nSuppose you promised two different people that you would spend the same evening with them. You cannot keep both promises.\nWhichever one you keep, you break the other.\nYou may look for another possibility.\nYou might move one meeting, explain the problem, or bring the two people together.\nBut suppose none of this works.\nThen you must choose.\nYet choosing one does not make the other promise disappear.\nNor must the chosen option suddenly appear good.\nIt may remain merely the less bad one.\nOr simply the one you can finally bring yourself to enact.\nChoice can settle action while conflicting convictions remain.\nChoice seems to require possibilities and often involves criteria, goals, rules, or boundaries. But the possibilities need not simply be given, and the criteria need not determine one answer.\nWe may even choose the procedure by which the decision is made, while conflicting convictions remain afterward.\nHow do possibilities appear?\nHow do we know which ones belong to the choice?\nHow do we know that we have considered them all?\nIn practice, we just choose without being able to say how all of this was settled.\nSo is choice where our doing begins?","id":"https://www.stefankober.de/essays/participation/03/","title":"Looking At Choice"},"https://www.stefankober.de/essays/participation/04/":{"body":"Hold up your fist and extend your index finger.\nDo it again.\nWhen I do this, I find no moment in which several possibilities appear and I choose one of them.\nWhat would the possibilities even be? Every possible moment at which I might move?\nI simply extend the finger.\nStill, it seems very clearly to be my doing.\nIt is quite different from someone else forcefully extending my finger. It is also different from my finger moving in a sudden involuntary jerk.\nWhatever distinguishes these cases, an observable act of choosing does not seem necessary.\nAfter a run, I take a bottle of water and unscrew it while continuing a conversation. I may barely notice what my hands are doing. There is no weighing of possibilities. No question appears. I do not choose between unscrewing the bottle and doing something else.\nI simply unscrew it and drink.\nYet afterwards I would have little difficulty saying that I opened the bottle. The action can be mine without becoming an object of deliberation while I perform it.\nMore complicated movements can work in much the same way. When practising a motor activity, movements that initially require attention can become increasingly fluent. At some point, deliberately controlling every part may make the activity worse.\nIn rope flow, for example, one movement can lead into another without my first choosing the next figure. A pattern emerges, like in musical improvisation. I can interrupt it or change direction. I can begin again.\nBut while it is happening, much of what I am doing is not preceded by a choice between explicit possibilities. Often I find myself monitoring what happens more than deciding each movement.\nStill, the movement remains recognizably mine.\nThe exact experience probably differs between people.\nIt is enough here that the phenomenon occurs.\nWalking, speaking, typing, playing an instrument, and many movements in sport can proceed without a sequence of choices corresponding to every movement performed. Many of these activities were once learned deliberately. They may still be interruptible or redirectable, and often depend on preparation and training.\nYet at the moment of action, much of the doing unfolds without an identifiable choice.\nChoice seems unable to mark the boundary of our doing.\nSome things we choose are clearly our doing.\nBut some things that are clearly our doing do not seem to involve choice at all.\nWe began with the possibility that choice might mark the boundary of our doing.\nIt does not seem to.\nBut where choice and doing come apart, we learn something about what such a boundary would have to account for.","id":"https://www.stefankober.de/essays/participation/04/","title":"Action Without Obvious Choice"},"https://www.stefankober.de/essays/participation/05/":{"body":"A doctor tells a child:\n\"Do not touch the wound.\"\nThe child understands.\nMaybe even agrees.\nLater, while playing, the child pretends that one hand is a spider crawling up the other arm.\nThe spider moves.\nUp the wrist.\nUp the forearm.\nAnd then the hand touches the wound.\nThe child did not choose to touch it. The wound may not even have been present in attention. What the child was doing was making a spider crawl up an arm.\nYet touching the wound was also something the child did.\nSuppose someone asks you to hold up a number with one hand.\nBut instead of choosing a number, you decide to choose randomly among familiar hand signs. The horns, the victory sign, the OK sign, or a fist.\nOnly afterwards do you look at how many fingers are extended.\nMaybe you did not know the number before looking.\nYou chose the sign. Yet by choosing it, you also produced a number.\nThe number was your doing, but it was not what you actually chose.\nWhat we do can extend beyond what we chose to do.\nWe may do one thing and thereby do another.","id":"https://www.stefankober.de/essays/participation/05/","title":"Choosing One Thing, Doing Another"},"https://www.stefankober.de/essays/participation/06/":{"body":"Suppose you set an alarm before going to sleep.\nYou choose the time. Maybe you have an early appointment or want to go running.\nThen you sleep. Hours later the alarm rings.\nThe choice happened yesterday. It changed what happens now, but the choice itself is no longer happening.\nYou may not even remember immediately why you set the alarm.\nAnd when it rings, another situation has already formed.\nYou are tired. The bed is warm. Getting up may no longer seem like a particularly good idea.\nThe earlier choice still matters. But it does not simply govern the later moment.\nSometimes we choose earlier precisely because we expect the later situation to change what seems convincing.\nYou are angry. You want to send a message.\nBut you know that anger changes what appears reasonable.\nSo you decide: Not tonight.\nYou put the phone away.\nMaybe you even write the message and leave it unsent.\nThe choice changes the conditions under which you will act later.\nIt creates distance. It gives other convictions time to return. In the morning, the message may still seem right. Or embarrassing. Or unnecessary.\nThe same structure can extend much further.\nAn investor decides in calm circumstances how to respond to a large fall in the market.\nThe rule is simple: Do not sell merely because prices fall.\nYears later prices collapse. Losses become visible, other investors panic, and news stories predict disaster. The conviction that selling immediately is the only sensible thing to do may become very strong.\nThe earlier strategy still exists. Maybe even in writing. But the earlier choice has not prevented the later conviction from forming. The person who made the rule and the person facing the crash are the same person. Yet they do not stand in the same situation.\nWhat convinced the person in one set of circumstances does not necessarily convince them in another.\nSo what remains after a choice has been made?\nSometimes what remains is a memory, a rule, an alarm, a promise, a habit, a note left for oneself, or other people who remember what we said we would do.\nThe choice can leave many things behind. But these things are not the choice itself.\nThey participate in what happens later.\nThe earlier choice need also not remain present in memory.\nYou may get up when the alarm rings without remembering why you chose that particular time. If the alarm still rings because you once set it, the earlier choice remains plainly involved in what happens now.\nOther cases are different.\nYou may have stopped sending angry messages years ago and now simply wait before replying. An earlier decision may have helped form that habit.\nBut today's waiting is not simply the earlier choice continuing to act. The connection is historical rather than immediate.\nThe investment strategy is looser still.\nAn earlier choice may remain available as a rule or reminder. But when the market falls, the later action arises in a new situation. You may be forced to choose again.\nWhat remains of a choice differs from case to case.\nIt may be preserved in something we deliberately set in motion, survive through habits it helped form, or remain only as one consideration among others.\nThe history matters without becoming a permanent command.\nWe can create reminders, change the environment, establish rules, build habits, create obligations, and make some actions easier or harder.\nA choice occurs at a particular time.\nChoice can reach into the future.\nBut it does not control it.\nWe may continue what we once chose, revise it, or later act without any identifiable choice at all.\nYet all of these can still be our doing.","id":"https://www.stefankober.de/essays/participation/06/","title":"The Reach Of Choice"},"https://www.stefankober.de/essays/participation/07/":{"body":"Suppose you decided to go running tomorrow morning.\nTomorrow comes. You wake up and think: No. I am not going.\nYou may even say it aloud.\nThe earlier choice has been revoked. This seems straightforward.\nYou chose one thing yesterday. Today you choose otherwise.\nThe later choice replaces the earlier one. But not every change of heart works that way.\nSuppose you decided never to answer work messages after eight in the evening. Then one evening a colleague writes: \"The server is down.\" You reply. Maybe you do not think you have abandoned the rule at all.\nThe situation simply does not seem to be one to which it applies. The earlier choice remains. What changed is how the present situation is understood.\nSometimes even that does not happen.\nYou made an investment plan. You still think the plan is good and that you should follow it.\nThen the market falls sharply. You watch the losses grow. And you sell. You may still be convinced, even while doing so, that selling is contrary to the strategy you chose.\nThe earlier choice has not been revoked. The rule has not been reinterpreted. Something else has become strong enough to override it in action.\nOr suppose you decided to finish a difficult task today.\nYou work for an hour. Then you stop.\nYou have not abandoned the plan or decided that it was a bad one. You tell yourself: Not now. I will continue later.\nThe choice remains in place, but its enactment is suspended. Whether you return to it is another matter.\nAnd sometimes there is no identifiable moment of reversal at all.\nYou once decided to practise an instrument every evening.\nFor a while you do.\nThen one evening you do not. A few days later you miss another.\nEventually weeks pass.\nMaybe you still vaguely think of yourself as someone who practises every evening. But the old choice has lost its force. No second decision replaced it.\nYou never clearly said: I no longer intend to do this. You simply stopped.\nAn earlier choice may be explicitly revoked, reconsidered in its application, overridden in action, suspended, or simply lose its influence without any clear later choice taking its place.\nThis makes it difficult to understand a life as a sequence of choices governing what follows.\nChoices matter. They can redirect what happens. They can leave rules, habits, promises, and altered circumstances behind.\nThese can help an earlier choice survive later pressure.\nWe can make some actions easier, others harder, create reminders, establish routines, or involve other people.\nChanges in circumstances can have the opposite effect. A routine that seemed stable at home may disappear during a journey, a move, or another interruption of ordinary life.\nAny choice can be revised, resisted, forgotten, or simply lose its force.\nAn earlier choice does not govern what follows merely because it was once ours.\nEven here, there need not be a choice.","id":"https://www.stefankober.de/essays/participation/07/","title":"Revoking A Choice"},"https://www.stefankober.de/essays/participation/08/":{"body":"Suppose you decide to build a table.\nYou draw a rough plan, buy wood, measure twice, and cut once. You still make a mistake and replace one piece. Then you leave the work unfinished for a week and return to it later. Eventually the table stands in front of you.\nYou built it. That description seems natural.\nBut there was no single moment in which building the table happened.\nThere were many actions, some deliberate, some habitual, some corrected halfway through, and some probably forgotten by the time the work was done.\nThe original choice to build a table mattered. But it did not govern every movement that followed.\nAnd the table was not built by the choice alone.\nThe same is true when learning a piece of music, training for a race, restoring a neglected garden, or writing a book. These activities can take weeks, months, or years. They contain pauses, changed plans, mistakes, new ideas, and periods in which little happens at all.\nThe original reason for beginning may remain present throughout, change over time, or disappear almost completely while the activity continues in another form.\nSomething that began as a side effect can even become the main reason for continuing.\nStill, afterwards we say:\n\"I learned this.\"\n\"I restored that.\"\n\"I wrote it.\"\nThe doing extends across time even though no single choice extends across time in the same way.\nWhat we call one doing may contain many smaller doings, choices, revisions, and periods in which no choice is present at all.\nConsider writing a book.\nMaybe you begin with a clear idea of what it should become. Later that idea no longer convinces you. You remove a chapter, and another may appear unexpectedly. At some point you might abandon the project for months because nothing seems to work. When you return, you may no longer remember some of the reasons behind earlier decisions.\nYet those decisions remain in the text.\nSome sentences were carefully constructed. Others appeared quickly and survived every later revision. Someone else may have suggested a change that became indispensable.\nThe finished book contains all of this.\nIt would be strange to conclude that you did not write it because no single plan or choice remained unchanged from beginning to end.\nWhat makes the book your doing is not that every part of its history was chosen in advance.\nYou repeatedly returned to it, altered it, abandoned parts, added others, and brought it closer to what it eventually became.\nThis seems to be true beyond individual projects.\nA household can maintain a home over many years.\nNo single decision of one person does that. People clean and repair things, buy and replace them, forget some problems and notice others, organize, neglect, and begin again. Different people contribute different things at different times.\nStill, it can make sense to say that they maintained the home together.\nA company may build a product that no single person designed or made. Towns preserve infrastructure and practices across generations, and scientific fields can develop methods through the work of people who never met one another.\nHere the language of doing begins to widen.\nThe participants change. The choices change. Some contributions are deliberate and visible. Others become routines, institutions, tools, or inherited practices. What one person leaves behind becomes part of the situation in which another acts.\nThe larger the doing becomes, the harder it is to identify one chooser behind it. Yet the doing does not disappear. It becomes distributed across actions, time, and people.\nEarlier choices can shape later conditions. Later actions can revise what earlier participants began. Some contributions remain visible. Others disappear into the structure of what has been built.\nWe may choose some parts. Others may arise from habit, training, circumstances, or what others have already done. Yet they can all become part of what we did.\nThis is one reason participation is a better word than control. We do not need to have chosen the whole course of something in order to have had a part in bringing it about. And what we bring about can become part of the conditions under which others act after us.","id":"https://www.stefankober.de/essays/participation/08/","title":"Doing Across Time"},"https://www.stefankober.de/essays/participation/09/":{"body":"We began by asking what in our lives can properly be called our doing. Choice seemed an obvious place to look.\nChoice is real. We can stop, consider possibilities, select one, and act on it. But choice did not mark the boundary we were looking for. Something can be our doing without being preceded by a separate choice at every step.\nA learned activity may unfold while we monitor what happens. We may intervene only when something calls for correction. Preparation done long before may become effective in the moment. An earlier course may be maintained against resistance or abandoned when it no longer holds.\nA chess move may be preceded by deliberation, while a movement in sport emerges from training and the situation. We can also initiate a calculation deliberately even though its result is not ours to choose.\nThese are not merely stronger and weaker versions of one process. They are different ways in which something can be our doing.\nChoice is one of them. It is not the whole of participation.\nSometimes our reasons are easy to state.\nYou choose the screwdriver because you want to tighten the screw. The screwdriver is not simply better than the hammer or the knife. It is better for what you are trying to do.\nSometimes a reason becomes visible when we intervene.\nYou stop because something looks dangerous. You change course because another possibility has become available. But a reason need not accompany every part of an activity separately.\nSomeone may be dancing, skating, playing an instrument, or riding a motorcycle.\nWhy that exact movement? There may be no useful answer.\nWhy continue the activity? There may be one. A reason can belong to the larger course without explaining each movement within it.\nSometimes the question arises only afterwards.\nWhy did I say that?\nWhy did I stop?\nWhy did I stay?\nWhy did I keep returning to this?\nAn answer may form. Maybe I was afraid, wanted approval, or cared more than I had realized. Maybe the old course no longer convinced me. Such answers are convictions too. They can stabilize, change, or dissolve.\nA later explanation of our own action is not automatically the true motive. It is another attempt to understand our participation.\nPatterns of doing can nevertheless tell us something about orientation.\nWe return to some questions, protect some things, prepare for some possibilities, and maintain some courses while abandoning others.\nNo single action need reveal very much. Across time, however, what we repeatedly do can provide evidence about what matters, what we expect, and what has become sufficiently stable to guide us.\nNone of this begins from an empty situation. We enter circumstances already underway: a language we speak, practices we learned, institutions and relationships already there, events that happened before we arrived, and convictions and distinctions we did not originate. Orientation precedes any particular act of reflection or choice. Yet what we do within it can alter what happens next.\nWe can ask a question that another person later finds difficult to answer. We can introduce a possibility they had not considered. We can teach a procedure, preserve a comparison, challenge a claim, or build something that remains available after the action itself is over. Earlier action can become part of the conditions under which later action and conviction occur.\nThe result is not under the original actor's command.\nA question may be ignored, a possibility fail to convince, or a method be learned and later rejected. A promise can change another person's expectations in ways we did not foresee.\nWhat we do can matter without determining what follows.\nThe cases examined here do not reveal one obvious mechanism common to everything we call our doing.\nExplicit choice is sometimes present and sometimes absent, and control may be extensive or limited. Preparation can occur long before action, while fluent activity may outrun conscious deliberation. Consequences can also follow from what we do without having been separately intended.\nComprehensive control is not required for something to count as our doing. Nor does our doing reduce to isolated moments of explicit choice.\nParticipation names this broader involvement.\nIt does not explain the metaphysics of agency. It marks a difference that the examples repeatedly make visible: between something merely happening around us and our having a part in what happens.\nThat is enough for Conviction Formation Theory as a preliminary account of how finite agents can continue to inquire and act without direct control of conviction or final settlement.\nWe do not choose directly what will convince us, whether a deliberately posed question will become genuinely puzzling, or which possibility will eventually acquire force.\nWe can nevertheless ask, search, prepare, compare, practise, challenge, defend, and enter procedures whose results are not ours to determine.\nWhat we do can alter the conditions under which conviction forms. Those altered conditions can in turn become part of someone else's orientation.\nWe do not stand outside conviction formation and direct it. But neither are we absent from it.","id":"https://www.stefankober.de/essays/participation/09/","title":"Participation"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/":{"body":"","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/","title":"Questions, Possibilities, And Formal Systems"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/01/":{"body":"Conviction does not fill orientation evenly.\nSome things are settled enough that we simply rely on them.\nThe floor will hold. This is the road home. That person is a friend.\nSeven plus five is twelve.\nThe meeting begins at nine.\nOther parts remain uncertain, incomplete, unstable, or contested.\nWhy did she say that? Will the project succeed?\nWhich explanation fits what happened? Was the measurement wrong?\nWhat should we do if the attack comes through another route?\nSometimes something that had seemed settled becomes uncertain again. A new fact no longer fits. An expected result fails to appear. Someone asks a question we cannot answer. An alternative we had not considered suddenly becomes visible.\nInquiry begins somewhere inside this mixture.\nIt does not begin from nothing. Most of orientation remains in place while some part becomes uncertain, tense, or newly visible.\nSomething that had remained in the background becomes an object of attention.\nA gap or tension becomes difficult to ignore. Something matters that we do not yet know how to settle.\nWe cannot simply choose what will convince us. But we can ask questions, search for alternatives, compare possibilities, preserve them outside memory, and enter procedures designed to constrain what happens next.\nThese activities do not determine the result of inquiry.\nThey change its conditions.\nHow far can such intervention go?","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/01/","title":"From Conviction to Inquiry"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/02/":{"body":"Questions\nSuppose you come home and find the kitchen window open.\nYou remember closing it.\nFor a moment there may be no question. You simply notice the open window.\nBut then questions begin to nag.\nDid I really close it?\nDid someone open it?\nWas somebody in the house?\nThe questions do not erase everything else you take to be the case. You still recognize the kitchen. You still know roughly what happened earlier in the day. You still understand what a window is and why an open one might matter.\nOnly part of the situation has become unsettled.\nQuestions often work like this.\nThey mark or create some local incompleteness within a background that continues to operate.\nThere is little reason here to search for an essence common to every grammatical question. Questions do many things. They request information, expose uncertainty, challenge assumptions, redirect attention, test competence, and reopen alternatives.\nSome are rhetorical, strategic, hostile, playful, or deceptive.\nA question in the sense used here directs attention toward something that is not yet settled.\nSometimes the unsettledness comes first. You are genuinely puzzled. Something does not make sense, and the question gives the puzzlement a form.\nSometimes the question comes first.\nA teacher asks:\n\"What assumption are you making here?\"\nYou may not have been puzzled at all. Only after trying to answer do you notice that your conclusion depends on something you had never examined.\nBeing puzzled is not obviously something we can simply decide to become.\nConviction Formation Theory extends the fundamental claim to questioning:\nWe can deliberately formulate a question, but we cannot simply decide that something will become genuinely questionable for us.\nBut there is an important difference. Unlike convictions, questions call for answers.\nA deliberately entertained conviction may later acquire convincing force if what we encounter supports it. A deliberately posed question has an additional possibility: the expected answer may fail to appear. That failure can itself make the question genuinely puzzling.\nA conviction can gain force through what supports it. A question can gain force through the failure of what should answer it.\nWe can deliberately ask what else could explain something, what we may be assuming, what would count against a conviction, or which possibility we have ignored.\nAt first such questions may be little more than learned techniques. Perhaps nothing follows.\nYou ask what would count against a conviction and immediately find a satisfactory answer.\nBut the situation changes when we expected to have an adequate answer and discover that we do not.\nThe question may not have been genuinely puzzling when we posed it. The failure to answer it can make it so.\nBy asking, we can place ourselves in conditions under which the absence of an answer may itself give the question force.\nWhat began as a learned technique can then become a genuine problem for us.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/02/","title":"Questions"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/03/":{"body":"Questions show what is still open, but they also show what has already been taken as settled.\nConsider: \"Who broke the glass?\"\nThe identity remains open.\nBut the question already contains a substantial commitment: somebody broke the glass.\nIf nobody did, the question has organized the situation badly.\n\"What happened?\"\nThis already treats something as an event that can be picked out and described.\n\"Where did it happen?\"\nThis relies on a spatial organization in which something can be located.\n\"When?\"\nThis relies on an ordered temporal structure.\n\"How did it happen?\"\nThis may ask for a process, mechanism, or sequence.\n\"Why?\"\nThat can do several different jobs.\n\"Why did the bridge collapse?\"\n\"Why did you leave?\"\n\"Why should we accept this?\"\n\"Why does this keep happening?\"\nThese questions may be asking about a cause, a motive, a justification, or some other connection that would make the situation intelligible.\nAn intelligible question depends on much that is not being questioned. It marks something as open while also revealing parts of the surrounding orientation that remain stable enough for the question to make sense.\nAn answer can shift inquiry into another part of the background structure on which the question depends.\n\"Why did the bridge collapse?\"\nThe material failed.\n\"Why did the material fail?\"\nThe materials were mixed incorrectly during manufacturing.\nThe first question concerned the collapse. Its answer connects that event to another process that had remained in the background, and that process can now become the object of inquiry in turn.\nIn a narrative context, this may amount to moving from one part of a background story to another. In other cases, inquiry may move into a procedure, a classification, a measurement practice, an assumption, or another part of orientation.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/03/","title":"What Questions Reveal"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/04/":{"body":"Questions also pass between people.\nIf I ask: \"Do you know where the key is?\"\nI do more than register a gap in my own orientation.\nI treat you as someone who may be able to fill it.\nOther questions do more.\nA teacher may ask a student to identify an assumption. A doctor might want to know which symptoms appeared first, while an investigator asks a witness what happened before the alarm. An engineer might ask whether anyone checked name resolution before replacing the server.\nA friend asks: \"Are you sure that is why she did it?\"\nA question can introduce a distinction or possibility that was not previously active for the person being asked.\nIt can make an assumption visible, demand a defense, redirect attention, or narrow the available responses.\nQuestions between people are not automatically neutral.\nA lawyer may ask a question designed to restrict what can be said, while an interrogator may use one strategically. A politician might pose a question to close inquiry rather than open it. Teachers sometimes ask questions whose answers they already know, and a friend may ask simply because something in another person's account seems incomplete.\nInquiry can be shared without being symmetrical.\nWho asks, who answers, and what relation exists between them affects what the question does.\nWe can deliberately introduce questions not only into our own inquiry, but into the conditions under which conviction forms for other people.\nWe cannot decide that the question will become puzzling for them.\nIt may leave their orientation untouched. They may have an answer ready, dismiss the question, misunderstand it, or simply not find it important.\nBut they may also discover, in trying to answer, that something they had taken for granted is harder to account for than they expected.\nThe question can then acquire a force that neither the person asking it nor the person answering it directly chose. Questioning another person is another form of indirect participation in conviction formation.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/04/","title":"Questions Between People"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/05/":{"body":"Return to the open window.\n\"Who opened it?\"\nSeveral answers may become available.\nI did and forgot.\nMy daughter did.\nThe wind pushed it open.\nSomeone entered.\nPerhaps one of these possibilities immediately feels likely.\nPerhaps none does.\nThe important change is that the question has created a space in which different answers can now compete.\nNot every question does this. Some request a missing value or a simple piece of information.\nBut many questions make alternatives available.\nThis can reverse something conviction had previously accomplished.\nSuppose you were convinced that you had left the window open yourself.\nThe burglary possibility might never become active.\nThen someone asks: \"Are you sure?\"\nOr: \"Wasn't it cold when you left?\"\nThe settled answer can become one possibility among others.\nIt is tempting to imagine all relevant possibilities as already present in some neutral space, waiting to be inspected.\nFor finite agents, they usually have to become available somehow.\nSome come from memory or imagination. Analogy may suggest others, or another person may propose one. A formal method can sometimes enumerate possibilities, while a change in description may alter which ones appear relevant. Expertise can make possibilities visible that a novice would not think to consider.\nSuppose someone investigates a computer outage.\nThe first question is: \"Which server failed?\"\nSeveral servers are examined.\nAn experienced engineer may instead ask: \"Did any server fail?\"\nPerhaps name resolution broke. The Monitoring may be wrong. Or the user report concerns another service.\nThe engineer has not merely evaluated the original alternatives better.\nShe has changed the possibility space.\nInquiry can have two distinct tasks: generating possibilities and evaluating them.\nGood evaluation does not repair a badly generated possibility space.\nA flawless ranking procedure applied to inadequate alternatives can produce a very orderly mistake.\nFor finite agents this creates a persistent difficulty. We often do not know whether every relevant possibility has been considered.\nSometimes, however, the structure of the possibilities itself gives us strong reasons to think that none are missing.\nTake a natural number.\nIt is either even or odd.\nTwo claims are involved here.\nFirst, the alternatives exclude one another. A natural number cannot be both even and odd.\nSecond, they exhaust the relevant possibilities. With respect to parity, there is no third case.\nThese claims are easy to run together, but they are different. A set of alternatives can fail because some overlap, because something has been left out, or both.\nIn the case of even and odd, a simple procedure makes the structure easy to inspect.\nImagine a natural number as a collection of pebbles and repeatedly remove them in pairs.\nEventually either no pebble remains or exactly one does.\nThere cannot be two remaining, because they would form another pair. Three would reduce to one, four to none, and so on.\nThe procedure supports both parts of the possibility space. The two outcomes exclude one another, and repeated pairing leaves no third outcome.\nThis is a particularly clear case.\nOther possibility spaces are supported very differently.\nSuppose a witness describes a shirt as red rather than orange.\nThe distinction is useful, but its boundary is not like the boundary between even and odd. One observer may say red-orange, another orange-red. Lighting can change the judgment. The uncertainty lies partly in how the possibilities themselves have been distinguished.\nYet fuzzy boundaries do not make the classification useless. A disputed red-orange shirt may still clearly not be blue or green.\nExhaustiveness raises another problem. Do our familiar color categories capture every relevant distinction?\nFor ordinary purposes they may work very well. But their structure depends partly on human perception, learned categories, and the purpose for which the distinction is being made. We may not possess anything like the pairing procedure that made the parity case so clear.\nPluto shows another way in which a possibility space can change.\nFor much of the twentieth century, Pluto was classified as a planet. Then astronomers discovered additional bodies sufficiently similar to Pluto that the existing classification came under pressure.\nEither the category of planets would have to expand, or the criteria distinguishing planets from other bodies would have to change.\nPluto was eventually reclassified.\nPluto itself was still there, following the same orbit. What changed was how astronomers classified bodies like it.\nSometimes revising the classification is enough. In other cases, inquiry does not merely add another possibility or alter the criteria separating existing categories. It changes the concepts through which the possibility space was organized.\nIs light a wave or a particle?\nTaken as a simple classification, the question appears to demand one of two answers. But the development of quantum theory did not amount merely to selecting the correct member of that pair or adding an overlooked third ordinary category. The concepts involved had to be reconsidered.\nThese cases differ in how much confidence we can place in the structure of the possibility space.\nWith even and odd, a simple procedure gives strong support to both exclusivity and exhaustiveness.\nWith color, useful distinctions remain despite uncertain boundaries.\nWith Pluto, new cases put pressure on the criteria separating existing categories.\nWith wave and particle, the alternatives themselves proved inadequate as the terms of the problem.\nPossibility spaces can be open not only because alternatives are missing, but because the distinctions used to generate them may themselves change.\nA possibility space is not simply a neutral container into which alternatives arrive.\nIt has to be generated and structured.\nConvictions help determine which possibilities are recognized and which distinctions seem relevant. Those distinctions then affect where boundaries are drawn, whether possibilities are treated as overlapping, and whether the resulting space appears exhaustive.\nSome of these convictions can be supported very strongly. Others remain practical and approximate, and new possibilities may force the structure to be revised.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/05/","title":"From Questions to Possibilities"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/06/":{"body":"What happens once several possibilities are available?\nSometimes one becomes sufficiently convincing that the others cease to matter.\nSuppose you ask: \"What caused the outage?\"\nAt first several explanations remain plausible. Then the logs show that a deployment introduced the failure.\nOther possibilities lose their force. One answer has become convincing enough to proceed with.\nThis is a form of relative closure. It need not be certainty. Conflicting evidence may reopen the question.\nIn other situations, closure would achieve little.\nYou are traveling tomorrow.\nRain is a serious possibility, but sunshine remains plausible.\nYou do not need to settle the meteorological question.\nYou take a light raincoat.\nThat action works across more than one possibility.\nSecurity planning often has this form.\nYou do not know whether an attacker will use phishing, credential stuffing, an exposed service, or a supply-chain weakness.\nA defense may be designed to work across several routes.\nStrategy can preserve plurality for practical reasons.\nOnce several possibilities are available, one of them may become convincing enough that the others lose their force. If that does not happen, several may remain live and have to be carried forward.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/06/","title":"Closure and Maintained Openness"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/07/":{"body":"Once questions and possibilities are available, inquiry can be shaped more deliberately.\nWe can ask what we had not previously asked, deliberately search for alternatives, or preserve several possibilities instead of allowing one to close the inquiry too early.\nSuppose six possibilities are competing in your head.\nYou compare the first with the second.\nThen you remember something relevant to the fourth.\nThe fifth disappears from attention.\nYou return to the second but no longer remember why it had seemed weak.\nNow write the six possibilities down. They persist when attention moves elsewhere.\nYou can return to one.\nCross another out.\nAdd a seventh.\nCompare two side by side.\nGive the list to someone else.\nNothing about writing guarantees a good inquiry. But the conditions have changed. Parts of the inquiry now persist outside immediate memory. They can be inspected repeatedly.\nTables can preserve comparisons, and diagrams can make relations easier to inspect. Checklists or measuring instruments may stabilize a procedure or standard. Symbolic notation and formal rules can impose stronger constraints by fixing distinctions and limiting which transformations are permitted.\nIn each case, some part of the inquiry has been made more explicit and less dependent on what happens to remain in attention.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/07/","title":"Constraining Inquiry"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/08/":{"body":"A formal system can specify objects, stabilize symbols, restrict permitted operations, and preserve intermediate steps.\nAnother person can inspect the same structure, and errors can sometimes be localized.\nA result can be reconstructed rather than merely asserted.\nCounting provides a simple example.\nA pile of stones lies on a table.\nYou count twelve.\nI count thirteen.\nWe can count again, perhaps moving each stone as it is counted or arranging them in a row. We might pair each stone with a numbered marker.\nIf we disagree again, we may be able to locate the skipped or duplicated stone.\nThe procedure does more than produce a number.\nIt organizes the disagreement.\nMeasurement adds further constraints.\nTwo people disagree about the length of a table.\nA measuring tape can reorganize the problem, but it does not give us a quantity independently of the conditions of measurement.\nThe measurement depends on standardized units, a suitable instrument, correct placement, an adequate reading, and sometimes calibration and uncertainty estimates.\nMuch of the stability associated with measurement is engineered.\nConditions have been constructed under which certain disagreements become easier to investigate.\nDiagrams do something different.\nA diagram can make several relations visible at once. They can be pointed at, compared, rearranged, and criticized.\nA geometrical construction, a circuit diagram, a state machine, and a dependency graph differ greatly in purpose, but all can make relations available for visual inspection.\nLogic makes constraint more explicit still.\nOnce a formal language and rules are operative, a derivation can be constructed step by step.\nEach transformation can be checked.\nIf two people disagree, they can move backward until they find the first point at which their judgments diverge.\nWas a premise introduced?\nOr a rule applied incorrectly?\nWas a variable substituted where it should not have been?\nFormalization does not remove the need for judgment.\nSomeone still has to decide what to formalize.\nThe notation has to be understood. Premises have to be supplied. Rules have to be interpreted and applied.\nThe formal system itself has to be appropriate to the task.\nBut within the system, some kinds of disagreement can become sharply constrained.\nAcross these examples, parts of inquiry move outside immediate memory and become easier to repeat or inspect. Intermediate states persist, some moves can be restricted, and errors can sometimes be localized. Other people can reconstruct what happened.\nDisagreement can move from: \"Your conclusion is wrong\" to: \"This step does not follow.\"\nThat is a substantial change in the conditions under which disagreement can be examined and convictions reconsidered.\nThe constraint is nevertheless local.\nFormal systems can make parts of inquiry explicit, repeatable, and inspectable, but they do not replace the wider orientation in which those parts operate. And their constraints carry force only if the system itself is convincing.\nA derivation still begins from premises. A measurement still depends on instruments, procedures, and interpretation. A formal model still has to be connected to some problem or domain.\nNor does all conviction formation proceed through reconstructible steps. Perception, practice, narrative, and affect can alter orientation in different ways.\nFormal systems are not a general model of conviction formation. They are an especially explicit way of constraining parts of inquiry.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/08/","title":"Formal Systems"},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/09/":{"body":"Questions, possibilities, and formal systems have done different things in the inquiry so far.\nA deliberate question may initially have little force. Yet if no adequate answer appears, the question can begin to persist in ways we did not choose.\nWe may become genuinely puzzled.\nPossibilities we had not entertained enter the inquiry.\nThey may come from memory, imagination, another person, expertise, changed description, or explicit enumeration.\nTheir generation matters because evaluation cannot compensate for alternatives that never entered the inquiry.\nPossibility spaces can themselves be structured more or less sharply.\nSome can be made exhaustive and mutually exclusive.\nOthers remain useful despite uncertain boundaries.\nInquiry may then close around one answer, or deliberately preserve several possibilities when action does not require settlement, or settlement is currently impossible.\nParts of inquiry can be externalized. Comparisons can be stabilized. Procedures can be repeated. Permitted moves can be restricted.\nFormal systems bring together stabilized notation, inspectable representations, repeatable procedures, and shared ways of working through problems. This changes some of the conditions under which convictions can form and be reconsidered.","id":"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/09/","title":"Questions, Possibilities, and Formal Systems"},"https://www.stefankober.de/essays/recursion-tables/":{"body":"An exploratory essay on making recursive definitions and their structure easier to inspect.","id":"https://www.stefankober.de/essays/recursion-tables/","title":"Recursion Tables"},"https://www.stefankober.de/essays/recursion-tables/01/":{"body":"Truth tables make a small logical structure visible.\nWittgenstein gave them a prominent role in the Tractatus, while related tabular representations were also developed by others around the same period. What matters here is not their exact history, but the representational move they make possible.\nConsider a logical connective such as conjunction.\nIts behavior depends on the truth values of the propositions it connects. Since there are only finitely many combinations of those truth values, they can all be written down.\nThe resulting table makes the relevant cases surveyable.\nInstead of keeping several rules in mind, we can look at one object and inspect them together.\nThis essay proposes a similar device for a different setting.\nSuppose values are constructed from a finite number of constructors, and functions on those values are defined recursively.\nInstead of listing combinations of truth values, we can list combinations of constructors.\nInstead of putting only final values into the cells, some cells may contain recursive expressions referring to structurally smaller inputs.\nWe will call such representations recursion tables.\nThe analogy with truth tables is limited but useful.\nTruth tables make finite semantic cases easy to inspect.\nRecursion tables aim to make two features of simple recursive definitions surveyable:\nwhether all constructor cases have been handled;\nwhether recursive calls move toward structurally simpler cases.","id":"https://www.stefankober.de/essays/recursion-tables/01/","title":"1. From Truth Tables to Recursion Tables"},"https://www.stefankober.de/essays/recursion-tables/02/":{"body":"Consider conjunction:\npqp ∧ q\nTTT\nTFF\nFTF\nFFF\nIn truth-functional semantics, the behavior of conjunction is determined by the truth values of its inputs.\nThere are four possible combinations. The table contains all of them.\nIf both propositions are true, their conjunction is true.\nOtherwise it is false.\nWith respect to the truth-functional cases represented here, the table makes the relevant possibilities explicit.\nThis gives it a useful kind of completeness.\nWe do not have to remember that perhaps another combination exists somewhere outside the table. Given two inputs that each have exactly two possible truth values, the four rows exhaust the combinations.\nThe usefulness of the table depends on something established beforehand:\neach proposition receives one of the two truth values;\nthe listed cases exhaust those possibilities.\nOnce that background is accepted, the table provides a compact representation of the whole case structure.\nRecursion tables begin from the same idea.\nBut instead of asking which values an expression can receive, we ask how its inputs can be constructed.","id":"https://www.stefankober.de/essays/recursion-tables/02/","title":"2. Truth Tables"},"https://www.stefankober.de/essays/recursion-tables/03/":{"body":"Consider the natural numbers.\nInstead of beginning with an already completed collection $\\{0,1,2,3,\\ldots\\}$ we can use the familiar constructive description of the natural numbers.\nThere are two constructors:\nzero is a natural number;\nif n is a natural number, then suc(n) is a natural number.\nStarting from zero, repeated use of suc gives:\nThis constructive presentation is central to approaches such as Martin-Löf type theory, which develops ideas connected to intuitionism, type theory, and the propositions-as-types tradition.\nEvery natural number constructed in this way has one of two forms.\nIt is either\nor\nfor some smaller natural number k.\nThat gives us a finite set of cases even though there are infinitely many natural numbers.\nA function on natural numbers can be defined by considering these forms.\nFor a function of one natural-number argument, there are two cases:\nFor a function of two natural-number arguments, there are four combinations:\nThis is where a table becomes possible.\nRecursive calls can also move to structurally smaller data.\nIf a recursive definition handles suc(k) by making a recursive call on k, the recursive call is made on structurally smaller data.\nFor example: $f(suc(k)) \\mapsto f(k)$\nremoves one suc.\nStarting with $f(suc(suc(suc(zero))))$ we move to $f(suc(suc(zero)))$, then $f(suc(zero))$, then $f(zero)$.\nA structurally recursive definition has two features worth watching:\nEvery constructor case must be handled.\nRecursive calls must move toward smaller inputs.\nA recursion table can make both visible.","id":"https://www.stefankober.de/essays/recursion-tables/03/","title":"3. Types, Constructors, And Cases"},"https://www.stefankober.de/essays/recursion-tables/04/":{"body":"Consider equality on natural numbers.\nThe function should return true when two natural numbers are the same and false otherwise.\nSince each input is either zero or suc(...), we begin with the four constructor combinations:\n=zerosuc(l)\nzero??\nsuc(k)??\nThree cases are immediate.\nzero equals zero.\nzero does not equal a successor.\nA successor does not equal zero.\nSo:\n=zerosuc(l)\nzerotruefalse\nsuc(k)false?\nOne case remains.\nTwo successors are equal exactly when what comes before their outer suc constructors is equal:\n$\nsuc(k)=suc(l)\\mapsto k=l.\n$\nThe completed table is:\n=zerosuc(l)\nzerotruefalse\nsuc(k)falsek = l\nThe table makes three things especially easy to inspect.\nCoverage\nEvery constructor combination appears.\nThere are two constructors for the first argument and two for the second.\nThe resulting four combinations all have entries.\nThis shows that no constructor case has simply been omitted.\nStructure\nThe rows and columns are not arbitrary classifications imposed on the numbers afterwards.\nThey come directly from the way natural numbers are constructed.\nEach input has one of the forms represented by the headers.\nThe table mirrors the structure of the type.\nRecursive direction\nOnly one entry is recursive:\n$\nsuc(k)=suc(l)\\mapsto k=l.\n$\nThe recursive comparison is performed on k and l, each structurally smaller than the input from which it came.\nIf both numbers continue to be successors, the same reduction can be repeated.\nEventually at least one side reaches zero.\nThe table does not establish termination merely by being a table.\nWhat it does is put two relevant features in plain view:\nall constructor combinations are covered;\nthe only recursive call is made on smaller arguments.\nIn this simple setting, these are precisely the kinds of features we inspect when checking that evaluation proceeds toward a base case.\nBut case coverage alone is not enough.\nConsider this table:\nfzerosuc(k)\nresult0f(suc(k))\nBoth constructor cases have entries.\nYet the second entry merely calls the function again on the same input.\nIt does not move toward zero.\nIf we evaluate\n$\nf(suc(zero)),\n$\nwe obtain\n$\nf(suc(zero)),\n$\nagain and again.\nThe table makes the problem visible precisely because coverage and recursive progress occupy separate places in the representation.\nA recursive definition can satisfy the first without satisfying the second.","id":"https://www.stefankober.de/essays/recursion-tables/04/","title":"4. A First Example: Equality On Natural Numbers"},"https://www.stefankober.de/essays/recursion-tables/05/":{"body":"The same representation can be used for other functions.\nConsider addition.\nThere are several possible recursive definitions of addition. We will use one that reduces the first argument.\nThe table is:\n+zerosuc(l)\nzerozerosuc(l)\nsuc(k)suc(k)suc(k + suc(l))\nThe base cases are straightforward.\nAdding zero to zero gives zero.\nAdding zero to suc(l) gives suc(l).\nAdding suc(k) to zero gives suc(k).\nThe final cell contains the recursive case:\n$\nsuc(k)+suc(l)\\mapsto suc(k+suc(l)).\n$\nThe recursive addition inside the outer suc has first argument k.\nThe original first argument was suc(k).\nSo one constructor has been removed.\nConsider:\n$\n2+2.\n$\nWritten using constructors:\n$\nsuc(suc(zero))+suc(suc(zero)).\n$\nApplying the recursive case gives:\n$\nsuc(suc(zero)+suc(suc(zero))).\n$\nApplying it again:\n$\nsuc(suc(zero+suc(suc(zero)))).\n$\nThe base case now applies:\n$\nsuc(suc(suc(suc(zero)))).\n$\nThat is 4.\nThe table places the base cases and the recursive direction in one representation.\nMultiplication can be defined similarly:\n*zerosuc(l)\nzerozerozero\nsuc(k)zero(k x suc(l)) + suc(l)\nIf either argument is zero, the result is zero.\nThe recursive case is:\n$suc(k)\\times suc(l)\\mapsto(k\\times suc(l))+suc(l).$\nAgain, the multiplication on the right has a smaller first argument.\nThe original problem contained suc(k).\nThe recursive multiplication contains k.\nThe definition reduces the multiplication structurally while using addition to construct the result.","id":"https://www.stefankober.de/essays/recursion-tables/05/","title":"5. Addition And Multiplication"},"https://www.stefankober.de/essays/recursion-tables/06/":{"body":"Recursive definitions and proofs by structural induction have a closely related shape.\nRecursion defines an object or function by following the constructors of its inputs.\nStructural induction proves a property by following the same constructor structure.\nFor natural numbers, an inductive proof typically has two parts:\nestablish the property for zero;\nestablish that, if it holds for k, it also holds for suc(k).\nThis resembles a recursive definition because both follow the same way natural numbers are built.\nRecursion tables can make that common structure easier to notice.\nConsider the statement:\n$$\nn+zero=n.\n$$\nFor the particular definition of addition used above, the relevant column is already:\n+zero\nzerozero\nsuc(k)suc(k)\nThere are only two possible constructor forms for n.\nWhen n is zero, adding zero returns zero.\nWhen n is suc(k), adding zero returns suc(k).\nFor this definition, no additional inductive argument is required: the two possible forms of n are already represented directly by the defining clauses.\nMany properties of recursively defined functions are not themselves part of the definition.\nA recursion table may show how the function handles each constructor case and where its recursive calls go.\nBut if we want to prove some further property of the function, we may still need an inductive argument.\nThe table can help by making the relevant constructor structure visible, but it does not supply that proof by itself.\nThe table can nevertheless help by showing the constructor structure that such arguments will have to respect.\nThe same idea extends naturally to algorithms on other inductive data.\nLists\nA finite list can be presented using two constructors:\nthe empty list [];\na list formed by attaching an element x to another list xs, written x :: xs.\nThe length function can then be written as:\n$\nlen([\\ ])=0\n$\nand\n$\nlen(x::xs)=1+len(xs).\n$\nAs a table:\nlen[]x :: xs\nresult01 + len(xs)\nThere are two constructor cases and both are covered.\nThe recursive case calls len on xs.\nSince xs is the tail from which x :: xs was constructed, it is structurally smaller.\nThe same pattern appears in many recursive programs involving lists, trees, syntax trees, expressions, and other inductively constructed data.","id":"https://www.stefankober.de/essays/recursion-tables/06/","title":"6. From Recursion To Induction And Algorithms"},"https://www.stefankober.de/essays/recursion-tables/07/":{"body":"Recursion tables externalize some of the structure we would otherwise have to keep track of while reading a recursive definition.\nFor simple examples, two questions become especially visible:\nHave all constructor cases been handled?\nand:\nWhen recursion occurs, does it move toward structurally smaller data?\nBase cases and recursive cases become visually distinguishable.\nRecursive reduction can be compared directly with the structure represented in the row and column headers.\nThis can reduce part of the cognitive burden of understanding a definition.\nA recursion table does not by itself show that a definition is correct or that every relevant assumption has been made explicit.\nThis is what recursion tables are meant to add.\nThey may be useful pedagogically because they give a reader something compact to inspect before moving to more formal reasoning.","id":"https://www.stefankober.de/essays/recursion-tables/07/","title":"7. Visibility"}},"docInfo":{"https://www.stefankober.de/":{"body":36,"title":2},"https://www.stefankober.de/about/":{"body":68,"title":0},"https://www.stefankober.de/articles/":{"body":44,"title":1},"https://www.stefankober.de/essays/":{"body":28,"title":1},"https://www.stefankober.de/essays/conviction-formation-theory/":{"body":70,"title":3},"https://www.stefankober.de/essays/conviction-formation/":{"body":0,"title":2},"https://www.stefankober.de/essays/conviction-formation/01/":{"body":447,"title":4},"https://www.stefankober.de/essays/conviction-formation/02/":{"body":294,"title":2},"https://www.stefankober.de/essays/conviction-formation/03/":{"body":541,"title":4},"https://www.stefankober.de/essays/conviction-formation/04/":{"body":395,"title":5},"https://www.stefankober.de/essays/conviction-formation/05/":{"body":701,"title":5},"https://www.stefankober.de/essays/conviction-formation/06/":{"body":119,"title":2},"https://www.stefankober.de/essays/conviction-formation/07/":{"body":240,"title":4},"https://www.stefankober.de/essays/conviction-formation/08/":{"body":415,"title":3},"https://www.stefankober.de/essays/conviction-formation/09/":{"body":284,"title":3},"https://www.stefankober.de/essays/conviction-formation/10/":{"body":689,"title":3},"https://www.stefankober.de/essays/conviction-formation/11/":{"body":477,"title":4},"https://www.stefankober.de/essays/participation/":{"body":0,"title":1},"https://www.stefankober.de/essays/participation/01/":{"body":91,"title":1},"https://www.stefankober.de/essays/participation/02/":{"body":169,"title":1},"https://www.stefankober.de/essays/participation/03/":{"body":318,"title":2},"https://www.stefankober.de/essays/participation/04/":{"body":226,"title":4},"https://www.stefankober.de/essays/participation/05/":{"body":96,"title":5},"https://www.stefankober.de/essays/participation/06/":{"body":336,"title":2},"https://www.stefankober.de/essays/participation/07/":{"body":259,"title":2},"https://www.stefankober.de/essays/participation/08/":{"body":380,"title":2},"https://www.stefankober.de/essays/participation/09/":{"body":441,"title":1},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/":{"body":0,"title":4},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/01/":{"body":123,"title":2},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/02/":{"body":250,"title":1},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/03/":{"body":144,"title":2},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/04/":{"body":165,"title":3},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/05/":{"body":561,"title":2},"https://www.stefankober.de/essays/questions-possibilities-and-formal-systems/06/":{"body":111,"title":3},"https://www.stefankober.de/essays/questions-poss